// Playwright Fixture mintát követve mindent kitakarít a háttérben!
// fixtures/BaseTest.ts
// Az "as" felülírást jelenti, az eredetit felülírjuk. import { test as base, devices, BrowserContext, Page } from "@playwright/test";
import { LoginPage as LoginPage } from "../pages/LoginPage"; // 1. Lépés: Definiáljuk a fixture-ök típusait (milyen Page Objectjeink lesznek)
type MyFixtures = { // Első felhasználó környezete: context: BrowserContext; // Oldalváltáshoz kell. page: Page; loginPage: LoginPage; // Második felhasználó környezete: page2: Page;
}; // 2. Lépés: Kiterjesztjük az alap 'test' objektumot
export const test = base.extend<MyFixtures>({ // Minden fixture egy aszinkron függvény, ami megkapja a 'page' és a 'use' paramétert // Példányosítjuk az osztályt // Első lapfül loginPage: async ({ page }, use) => { // Átadjuk a tesztnek használatra await use(new LoginPage(page)); }, // Oldalváltáshoz kell. // Másik lapfül. page2: async ({ context }, use) => { // 1. Megkeressük az ELSŐ lapfület, ami a teszt indulásakor már létezik const firstTab = context.pages()[0]; // 2. Megnyitjuk a MÁSODIK lapfület (ez ekkor előtérbe ugrik) const newTab = await context.newPage(); // 3. Ha az első fül már létezik, AZONNAL visszaváltunk rá if (firstTab) { await firstTab.bringToFront(); } // 4. Átadjuk a másodlagos lapot a tesztnek await use(newTab); // 5. A teszt végén automatikusan bezárjuk a második fület await newTab.close(); }, /* loginPage2: async ({ page2 }, use) => { await use(new LoginPage(page2)); }, */
}); // 3. Lépés: Újraexportáljuk az 'expect' funkciót is, a kényelmesebb importálásért
export { expect } from "@playwright/test"; // Minden teszt után lefut.
test.afterEach(async ({ context }) => { await context.close();
});

