A csv használatához kell egy külön csomag, írd be azt a terminálba a letöltéséhez: npm install csv-parse A POM fejezetben lévő LoginPage osztály használjuk a lenti tesztnél. data/LoginData.csv: username,password,expected,run
standard_user,secret_sauce,success,yes
locked_out_user,secret_sauce,error,no
problem_user,secret_sauce,success,yes utils/csvReader.ts: import fs from "fs";
import * as csvParseSync from "csv-parse/sync"; export function readCSV(filePath: string) { // Adj hozzá 'utf-8'-at, hogy biztosan szövegként olvassa be const fileContent = fs.readFileSync(filePath, "utf-8"); const records = csvParseSync.parse(fileContent, { columns: true, // A fejlés a mezőneveket tartalmazza. skip_empty_lines: true, }); return records;
} login.csv.spec.ts import { expect, test } from "@playwright/test";
import { LoginPage } from "../pages/LoginPage";
import { readCSV } from "../utils/csvReader"; // Jobb klikk a fájlon és Copy Relative Path. /-re figyelj!
const loginData = readCSV("data/LoginData.csv"); // Soronként haladunk, az any-val elfogadunk minden típust.
loginData.forEach((data: any) => { // Ha nem true az értéke, akkor ne csináljon semmit. if (data.run !== "true") return; // Backtick (Visszafelé dőlő ékezet)-t használj! test(`Login Test - ${data.username}`, async ({ page }) => { const loginPage = new LoginPage(page); await loginPage.gotoLoginPage(); await loginPage.login(data.username, data.password); if (data.expected === "success") { await expect(page).toHaveURL("https://www.saucedemo.com/inventory.html"); } else { await expect(loginPage.errorMessage).toBeVisible(); } });
});

