A html kódba ezt írd bele, rakhatod a head, vagy a body-ba is. <!--defer: A script csak akkor fut le, amikor a HTML teljesen betöltődött.--> <script src="script.js" defer></script> Egy komponens id-jára, így kell hivatkozni: document.getElementById("fname"); var t=document.getElementById("fname"); t.value; //output: '' //Beírom az input mezőbe azt, hogy Bobby. t.value; //output: 'Bobby' Egy komponens value-ra való hivatkozás: //A html-ben van egy gomb, aminek a value-ja SuBmit. var c=document.querySelector('input[value="SuBmit"]'); c.value; //'SuBmit' c.value='SEND', //'SEND' //Elem szövegét módosítjuk. pl.: div,p , span
document.querySelector(".number").textContent = 13; //Szám beállítása az input mezőben. ez lehet input, vagy textarea
document.querySelector(".guess").value = 23; Típus csekkolás // 1. Az elem szövegként jön ki (string) let a = document.querySelector(".number").textContent; typeof a; // "string" // 2. Átalakítás számmá a = Number(a); typeof a; // "number" A táblázat összes cellájára való hivatkozás: var td =document.getElementsByTagName("td"); td[0]; // → első td , maga az HTML elem, output: <td>1</td> td[0].innerHTML; //→ az elem belsejében lévő tartalom (szöveg vagy HTML) //output: 1 Billentyű lenyomás eseményfigyelő: Figyeli, hogy a felhasználó lenyomott-e a billentyűzeten egy gombot, azt is nézi, ha nem egy input mezőben nyomott meg valamit. addEventListener mindig függvényt vár, nem a függvény azonnali meghívását. window.addEventListener('keypress',processKey); function processKey(evt){ console.log(evt); } //output: KeyboardEvent {isTrusted: true, key: 'f', code: 'KeyF', location: 0, ctrlKey: false, …} Ezzel, csak a betűket írjuk ki: window.addEventListener('keypress',processKey); function processKey(evt){ console.log (evt.key); } //output: f Click eseményhez: var button=document.querySelector('input[value="SuBmit"]'); button.addEventListener('click',kattintas); function kattintas(){ console.log("Kattintottal."); } Arrow függvény click eseményhez: window.addEventListener('click', () => { console.log("Kattintottál."); }); //Csak akkor fut, amikor valóban kattintanak az ablakban. Még rövidebb arrow függvény: addEventListener('click', () => console.log("kattintas")); Ezzel nem fog csinálni semmit az oldal, ha rákattintok a gombra: var button=document.querySelector('input[value="SuBmit"]'); button.addEventListener('click',function(evt){ evt.preventDefault() }); A class-on belül meg lehet adni alosztályt, ha van: // <button class="btn check">Check!</button>
//A btn class-on belül a check gombot kérjük le.
document.querySelector(".check").addEventListener();

